#!/bin/bash
sed -i '/<\/body>/i \    <div id="toast" style="display: none; position: fixed; bottom: 100px; left: 50%; transform: translateX(-50%); background: rgba(0,0,0,0.7); color: white; padding: 10px 20px; border-radius: 20px; z-index: 2000; font-size: 14px; white-space: nowrap;"><\/div>\n    <script>\n        function showToast(msg) {\n            const toast = document.getElementById('\''toast'\'');\n            toast.textContent = msg;\n            toast.style.display = '\''block'\'';\n            setTimeout(() => { toast.style.display = '\''none'\''; }, 2000);\n        }\n    <\/script>' ./mobile/cuotiben.html
